package dev.veltraph.client.navigation;
import dev.veltraph.client.game.GameArea;
import dev.veltraph.client.world.Vec3;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class AutomaticCommandReceiptTest {
    private static final Object ROOT=new Object(),PARENT=new Object(),PLAYER=new Object(),WORLD=new Object(),CONNECTION=new Object(),CONFIG=new Object(),SERVICE=new Object(),LEG=new Object();
    private static LegacyTravelPublicationIdentity.State state(){return new LegacyTravelPublicationIdentity.State(ROOT,PARENT,PARENT,PARENT,PLAYER,WORLD,CONNECTION,CONFIG,3,1,SERVICE,7,11,13,LEG,true,true,true);}
    private static TravelAtlas.Shortcut shortcut(){return new TravelAtlas.Shortcut("ranked",TravelAtlas.Kind.FAST_WARP,GameArea.GARDEN,"minecraft:overworld",new Vec3(.5,70,.5),new Vec3(20.5,70,.5),null,null,"express","rank:express","Express unlocked","Express rejected",1,0);}
    private static AutomaticCommandReceipt.Issue issue(){return new AutomaticCommandReceipt.Issue(state(),shortcut(),1,4,100,10100);}
    private static AutomaticCommandReceipt.Submission sent(){var p=new AutomaticCommandReceipt.Submission(issue());p.open();p.attempted();assertTrue(p.submitted(state(),"warp express",110));p.returnedNormally();p.close();return p;}
    @Test void commandOnlyFirstPublicationNeedsNoCameraTicket(){var p=sent();assertTrue(p.dispatched());assertEquals(13,issue().context().publicationSerial());}
    @Test void actualIssuedAtlasDestinationIsExact(){assertEquals("warp express",issue().command());}
    @Test void noOutgoingReceiptCannotBecomeDispatch(){var p=new AutomaticCommandReceipt.Submission(issue());p.open();p.attempted();p.returnedNormally();assertFalse(p.dispatched());assertTrue(p.attemptedSend());}
    @Test void submissionBeforeWindowRefused(){var p=new AutomaticCommandReceipt.Submission(issue());assertFalse(p.submitted(state(),"warp express",110));}
    @Test void submissionWithoutActualAttemptRefused(){var p=new AutomaticCommandReceipt.Submission(issue());p.open();assertFalse(p.submitted(state(),"warp express",110));}
    @Test void arbitraryCommandRefused(){var p=new AutomaticCommandReceipt.Submission(issue());p.open();p.attempted();assertFalse(p.submitted(state(),"warp other",110));}
    @Test void appliedOnlyAfterNormalReturn(){var p=new AutomaticCommandReceipt.Submission(issue());p.open();p.attempted();p.submitted(state(),"warp express",110);p.observe(state(),5,120,shortcut().arrival());assertNull(p.applied());}
    @Test void actualAppliedPositionAndNonceRetained(){var p=sent();p.observe(state(),5,120,shortcut().arrival());assertNotNull(p.applied());assertEquals(1,p.applied().issue().nonce());assertEquals(5,p.applied().serial());}
    @Test void newerSerialAloneCannotQualify(){var p=sent();p.observe(state(),5,120,new Vec3(21.5,70,.5));assertNull(p.applied());}
    @Test void staleBaselineRefused(){var p=sent();p.observe(state(),4,120,shortcut().arrival());assertNull(p.applied());}
    @Test void originalDeadlineNeverExtended(){var p=sent();p.observe(state(),5,10100,shortcut().arrival());assertNull(p.applied());}
    @Test void observationBeforeSubmissionRefused(){var p=sent();p.observe(state(),5,109,shortcut().arrival());assertNull(p.applied());}
    @Test void nonfinitePositionRefused(){var p=sent();p.observe(state(),5,120,new Vec3(Double.NaN,70,.5));assertNull(p.applied());}
    @Test void duplicateSubmissionRevokesInsteadOfRetry(){var p=sent();assertFalse(p.submitted(state(),"warp express",120));assertTrue(p.attemptedSend());assertNull(p.applied());}
    @Test void retirementCannotReopenIssuedNonce(){var p=sent();p.revoke();p.open();p.attempted();assertFalse(p.submitted(state(),"warp express",120));}
    @Test void eachConcreteIdentityDimensionIsRequired(){var a=state();Object[] replacements={new Object(),new Object(),new Object(),new Object(),new Object(),new Object(),new Object(),new Object(),new Object()};
        for(int i=0;i<9;i++){var b=new LegacyTravelPublicationIdentity.State(i==0?replacements[i]:a.root(),i==1?replacements[i]:a.parent(),i==2?replacements[i]:a.inputOwner(),i==3?replacements[i]:a.cameraAuthority(),i==4?replacements[i]:a.player(),i==5?replacements[i]:a.world(),i==6?replacements[i]:a.connection(),i==7?replacements[i]:a.config(),a.revision(),a.journey(),i==8?replacements[i]:a.service(),a.requestGeneration(),a.epoch(),a.publicationSerial(),a.activeLeg(),true,true,true);assertFalse(AutomaticCommandReceipt.same(a,b),"identity "+i);}}
    @Test void eachGenerationAndActiveLegRequired(){var a=state();for(int i=0;i<6;i++){var b=new LegacyTravelPublicationIdentity.State(a.root(),a.parent(),a.inputOwner(),a.cameraAuthority(),a.player(),a.world(),a.connection(),a.config(),a.revision()+(i==0?1:0),a.journey()+(i==1?1:0),a.service(),a.requestGeneration()+(i==2?1:0),a.epoch()+(i==3?1:0),a.publicationSerial()+(i==4?1:0),i==5?new Object():a.activeLeg(),true,true,true);assertFalse(AutomaticCommandReceipt.same(a,b),"generation "+i);}}
    @Test void registeredEnabledUsableRequired(){var a=state();for(int i=0;i<3;i++){var b=new LegacyTravelPublicationIdentity.State(a.root(),a.parent(),a.inputOwner(),a.cameraAuthority(),a.player(),a.world(),a.connection(),a.config(),a.revision(),a.journey(),a.service(),a.requestGeneration(),a.epoch(),a.publicationSerial(),a.activeLeg(),i!=0,i!=1,i!=2);assertFalse(AutomaticCommandReceipt.same(a,b));}}
    @Test void scopeLossAfterSubmissionRefusesAppliedPosition(){var p=sent();var a=state();var foreign=new LegacyTravelPublicationIdentity.State(a.root(),a.parent(),a.inputOwner(),a.cameraAuthority(),a.player(),a.world(),a.connection(),a.config(),a.revision(),a.journey(),a.service(),a.requestGeneration()+1,a.epoch(),a.publicationSerial(),a.activeLeg(),true,true,true);p.observe(foreign,5,120,shortcut().arrival());assertNull(p.applied());}
    @Test void invalidIssueRefused(){assertThrows(IllegalArgumentException.class,()->new AutomaticCommandReceipt.Issue(state(),shortcut(),0,4,100,10100));}
    @Test void closedExactContinuationAllowsOnlyNewLegIdentity(){var a=state();var closed=new LegacyTravelPublicationIdentity.State(a.root(),a.parent(),a.inputOwner(),a.cameraAuthority(),a.player(),a.world(),a.connection(),a.config(),a.revision(),a.journey(),a.service(),a.requestGeneration(),a.epoch(),a.publicationSerial(),null,true,true,true);assertTrue(AutomaticCommandReceipt.continuation(closed,a));}
    @Test void sameParentNewerPublicationCannotBeReadmitted(){var a=state();var closed=new LegacyTravelPublicationIdentity.State(a.root(),a.parent(),a.inputOwner(),a.cameraAuthority(),a.player(),a.world(),a.connection(),a.config(),a.revision(),a.journey(),a.service(),a.requestGeneration(),a.epoch(),a.publicationSerial()-1,null,true,true,true);assertFalse(AutomaticCommandReceipt.continuation(closed,a));}
    @Test void liveActiveLegCannotFabricateHandoff(){assertFalse(AutomaticCommandReceipt.continuation(state(),state()));}
    private static LegacyTravelPublicationIdentity.State changed(long generation,long serial,long revision){var a=state();return new LegacyTravelPublicationIdentity.State(a.root(),a.parent(),a.inputOwner(),a.cameraAuthority(),a.player(),a.world(),a.connection(),a.config(),revision,a.journey(),a.service(),generation,a.epoch(),serial,a.activeLeg(),true,true,true);}
    @Test void finalContextReadFollowsAllSourceCallbacks(){var events=new java.util.ArrayList<String>();assertTrue(AutomaticCommandReceipt.readyToSend(issue(),()->{events.add("geometry");events.add("access");events.add("root");return true;},()->{events.add("final-context");return state();}));assertEquals(java.util.List.of("geometry","access","root","final-context"),events);}
    @Test void geometryCallbackNewerRequestDeniesSend(){var current=new java.util.concurrent.atomic.AtomicReference<>(state());assertFalse(AutomaticCommandReceipt.readyToSend(issue(),()->{current.set(changed(8,13,3));return true;},current::get));}
    @Test void accessCallbackSameEpochPublicationDeniesSend(){var current=new java.util.concurrent.atomic.AtomicReference<>(state());assertFalse(AutomaticCommandReceipt.readyToSend(issue(),()->{current.set(changed(7,14,3));return true;},current::get));}
    @Test void sourceCallbackConfigRevocationDeniesSend(){var current=new java.util.concurrent.atomic.AtomicReference<>(state());assertFalse(AutomaticCommandReceipt.readyToSend(issue(),()->{current.set(changed(7,13,4));return true;},current::get));}
    @Test void deniedSourcePermissionNeverRequestsAnIssueContext(){var reads=new java.util.concurrent.atomic.AtomicInteger();assertFalse(AutomaticCommandReceipt.readyToSend(issue(),()->false,()->{reads.incrementAndGet();return state();}));assertEquals(0,reads.get());}
    @Test void reentrantReplacementLegCannotBorrowOriginalIssue(){var a=state();var replacement=new LegacyTravelPublicationIdentity.State(a.root(),a.parent(),a.inputOwner(),a.cameraAuthority(),a.player(),a.world(),a.connection(),a.config(),a.revision(),a.journey()+1,a.service(),a.requestGeneration(),a.epoch(),a.publicationSerial(),new Object(),true,true,true);assertFalse(AutomaticCommandReceipt.readyToSend(issue(),()->true,()->replacement));}
    @Test void revocationBeforeNativeAttemptCannotBecomeAttempted(){var proof=new AutomaticCommandReceipt.Submission(issue());proof.open();proof.revoke();proof.attempted();assertFalse(proof.attemptedSend());assertFalse(proof.dispatched());}
}
